steps.script:
$o=@{mode='safe_guard_hotfix';state='unknown';exit_code=$null;confirmed_guard=$false;chrome_untouched=$true}
try {
 $url='https://raw.githubusercontent.com/fabricelop/europapress-rss/db43ff0621b9d363c83aa68fb48a3c2dd0ca0976/windows/Update-TT-Editorial-Guard-Only.ps1'
 $file=Join-Path $env:TEMP 'tt-editorial-guard-only-pinned.ps1'
 Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $file -TimeoutSec 25 -ErrorAction Stop
 $source=Get-Content -LiteralPath $file -Raw -Encoding UTF8 -ErrorAction Stop
 if(-not($source.Contains('TT_EDITORIAL_GUARD_HOTFIX_V1') -and $source.Contains('51b6f70504cad0594a85f290e84d791edb38f09b') -and $source.Contains('CheckOnly'))){throw 'UNEXPECTED_SOURCE'}
 & "$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe" -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $file 1>$null 2>$null
 $o.exit_code=$LASTEXITCODE
 $guard='C:\TTiTTulares\TT-Editorial-Guard.js'
 if(Test-Path -LiteralPath $guard){
  $g=Get-Content -LiteralPath $guard -Raw -Encoding UTF8 -ErrorAction Stop
  $o.confirmed_guard=$g.Contains('function confirmedUserState(s,marker)') -and $g.Contains('TRANSMISSION_STATE')
 }
 $o.state=if($o.exit_code -eq 0 -and $o.confirmed_guard){'installed_verified'}else{'not_installed'}
}catch{$o.state='failed';$o.error_class=$_.Exception.GetType().Name}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
